async path => {
    const response = await fetch(`/api/v2/shops/shop-demo/${path}?limit=100`);
    if (!response.ok) throw new Error(`Expected ${path} GET to succeed, got ${response.status}`);
    const envelope = await response.json();
    return envelope.data;
  }

